	const capability = Object.freeze({}) as StagedCreatorSuccessorAdoption;
	stagedCustody.set(
210→		capability,
		Object.freeze({
			material: Object.freeze({
				descriptor: Object.freeze({ ...material.descriptor }),
				intent: material.intent,
			}),
			owner,
		})
	);
	return capability;
220→}

